  "vendor/fonts/public-sans-latin-700-normal.woff2",
  "vendor/fonts/public-sans-latin-800-normal.woff2",
  "vendor/fonts/public-sans-latin-ext-500-normal.woff2",
  "vendor/fonts/public-sans-latin-ext-600-normal.woff2",
  "vendor/fonts/public-sans-latin-ext-700-normal.woff2",
  "vendor/fonts/public-sans-latin-ext-800-normal.woff2",
